"Hi, I'm Pip!":"Salut, je suis Pip !",
"I'm a helper made by the Tenbright team using a computer, and my voice is made by a computer too.":"Je suis un assistant créé par l'équipe Tenbright avec un ordinateur, et ma voix est aussi faite par un ordinateur.",
"I collect light-beads.":"Je collectionne les perles de lumière.",
"Ten beads make a lantern.":"Dix perles font une lanterne.",
"Will you help me light the Kingdom?":"M'aideras-tu à illuminer le Royaume ?",
"Hint":"Indice",
"Try again.":"Essaie encore.",
"Homeschool or not sure":"École à la maison ou je ne sais pas",
"How long we keep it":"Combien de temps nous les gardons",
"How we use it":"Comment nous les utilisons",
"How we'll know":"Comment nous le saurons",
"Hundreds are the same, so look at the ones.":"Les centaines sont pareilles, donc regarde les unités.",
"I agree that Tenbright may keep my child's learning record on this device to choose their next activity and show me their progress.":"J'accepte que Tenbright conserve le dossier d'apprentissage de mon enfant sur cet appareil pour choisir sa prochaine activité et me montrer ses progrès.",
"I am this child's parent or legal guardian.":"Je suis le parent ou le tuteur légal de cet enfant.",
"I found {N} lanterns you can already light.":"J'ai trouvé {N} lanternes que tu peux déjà allumer.",
"Now the map knows where to start.":"Maintenant la carte sait où commencer.",
"I worked this out, but I made a mistake.":"J'ai fait ce calcul, mais je me suis trompé.",
"Can you find it?":"Peux-tu la trouver ?",
"I wrote it":"Je l'ai écrit",
"If we change what we collect or how we use it, we will ask for your consent again before the change applies to your child.":"Si nous changeons ce que nous recueillons ou la façon de l'utiliser, nous vous redemanderons votre consentement avant d'appliquer le changement à votre enfant.",
"If you switch on voice answers on the grown-ups page, your child can tap the Talk button and say a number or a short command such as \"next\".":"Si vous activez les réponses vocales sur la page adulte, votre enfant peut toucher le bouton Parler et dire un nombre ou une commande courte comme « suivant ».",
"Speech is turned into text by your browser on this device; Tenbright uses it only if the browser can promise this happens on the device.":"La parole est transformée en texte par votre navigateur sur cet appareil ; Tenbright ne l'utilise que si le navigateur peut garantir que cela se fait sur l'appareil.",
"The words are used once to read the answer and are then discarded.":"Les mots servent une seule fois à lire la réponse, puis sont effacés.",
"No audio and no transcript is recorded, kept or sent to us or anyone else.":"Aucun son ni aucune transcription n'est enregistré, conservé ou envoyé, ni à nous ni à personne.",
"The microphone is used only after a tap on Talk, for one short answer.":"Le micro n'est utilisé qu'après un appui sur Parler, pour une réponse courte.",
"Pip never asks your child to say their name or anything about themselves.":"Pip ne demande jamais à votre enfant de dire son nom ni quoi que ce soit sur lui-même.",
"You can switch voice answers off at any time.":"Vous pouvez désactiver les réponses vocales à tout moment.",
"In the full product this step will use an FTC-recognized method of verifiable parental consent.":"Dans le produit complet, cette étape utilisera une méthode de consentement parental vérifiable reconnue par la FTC.",
"This preview records your agreement on this device only.":"Cette version d'essai enregistre votre accord sur cet appareil seulement.",
"In this preview, everything stays in this browser on this device.":"Dans cette version d'essai, tout reste dans ce navigateur, sur cet appareil.",
"Nothing is sent to us or to anyone else.":"Rien n'est envoyé, ni à nous ni à personne.",
"The app loads no outside fonts, analytics, ads or trackers.":"L'application ne charge aucune police externe, aucun outil d'analyse, aucune publicité ni aucun traceur.",
"Pip's voice is recorded audio made with an AI voice model and included in the app; if a sentence has no recording, a voice built into your device reads it.":"En anglais, la voix de Pip est un enregistrement réalisé avec un modèle vocal d'IA et inclus dans l'application ; dans les autres langues, ou si une phrase n'a pas d'enregistrement, une voix intégrée à votre appareil la lit.",
