"Multiply the top; the bottom stays.":"Multiplie le haut ; le bas ne change pas.",
"How many pieces in each group?":"Combien de morceaux dans chaque groupe ?",
"Whole × top, same bottom.":"Entier × haut, même bas.",
"Each person gets {N}/{N} of a cup of juice.":"Chaque personne reçoit {N}/{N} de tasse de jus.",
"How much for {N} people?":"Combien pour {N} personnes ?",
