"Write both with the same number of decimal places.":"Écris les deux avec le même nombre de chiffres après la virgule.",
"Compare like whole numbers: {N} > {N}.":"Compare-les comme des nombres entiers : {N} > {N}.",
"Compare the tenths first.":"Compare d'abord les dixièmes.",
"Tenths first, then hundredths.":"D'abord les dixièmes, puis les centièmes.",
