"Add and subtract decimals":"Additionner et soustraire des décimaux",
"Line up the points!":"Aligne les virgules !",
"Write the decimal points one under the other.":"Écris les virgules l'une sous l'autre.",
"Fill empty places with zeros.":"Remplis les positions vides avec des zéros.",
"Add or subtract like whole numbers.":"Additionne ou soustrais comme avec des nombres entiers.",
