"Divide decimals":"Diviser des nombres décimaux",
"Dividing decimals.":"Diviser des décimaux.",
"{N} ÷ {N}: {N} tenths ÷ {N} = {N} tenths = {N}.":"{N} ÷ {N} : {N} dixièmes ÷ {N} = {N} dixièmes = {N}.",
