"Each gets {N}/{N}.":"Chacun reçoit {N}/{N}.",
"The top is what is shared; the bottom is how many share.":"Le haut, c'est ce qu'on partage ; le bas, entre combien on partage.",
"What is being shared, and by how many?":"Qu'est-ce qu'on partage, et entre combien ?",
