"Multiply fractions":"Multiplier des fractions",
"A part of a part.":"Une partie d'une partie.",
"Multiply the tops.":"Multiplie les nombres du haut.",
"Multiply the bottoms.":"Multiplie les nombres du bas.",
"Top times top, bottom times bottom.":"Haut fois haut, bas fois bas.",
"Multiply straight across.":"Multiplie tout droit.",
