"Divide with unit fractions":"Diviser avec des fractions unitaires",
"How many pieces fit?":"Combien de morceaux rentrent ?",
"{N} ÷ {N}/{N}: each whole holds {N} quarters, so {N}.":"{N} ÷ {N}/{N} : chaque tout contient {N} quarts, donc {N}.",
