"Move the digits.":"Déplace les chiffres.",
"Multiplies a decimal by {N}, {N} or {N} by writing zeros at the end instead of moving the digits.":"Multiplie un décimal par {N}, {N} ou {N} en écrivant des zéros à la fin au lieu de déplacer les chiffres.",
"Added zeros to a decimal":"A ajouté des zéros à un décimal",
