"Mixes up the tenths and hundredths places.":"Confond la position des dixièmes et celle des centièmes.",
"Tenths and hundredths swapped":"Dixièmes et centièmes inversés",
"Line up the decimal points first.":"Aligne d'abord les virgules.",
"Lines up the last digits instead of the decimal points when adding or subtracting decimals.":"Aligne les derniers chiffres au lieu des virgules en additionnant ou en soustrayant des décimaux.",
"Lined up the last digits":"A aligné les derniers chiffres",
"Count the decimal places.":"Compte les chiffres après la virgule.",
"Does the size of the answer make sense?":"La taille de la réponse est-elle logique ?",
"Multiplies or divides correctly but puts the decimal point in the wrong place.":"Multiplie ou divise correctement mais place la virgule au mauvais endroit.",
"Decimal point in the wrong place":"Virgule mal placée",
"How many halves fit in one whole?":"Combien de moitiés rentrent dans un tout ?",
"Thinks dividing always makes a number smaller, so multiplies when dividing by a fraction or decimal under {N}.":"Pense que diviser rend toujours plus petit, donc multiplie en divisant par une fraction ou un décimal inférieur à {N}.",
"Dividing always makes smaller":"Diviser rend toujours plus petit",
"Each part has a place value.":"Chaque partie a une valeur de position.",
"Multiplies each digit but writes the products side by side instead of adding them with their place values.":"Multiplie chaque chiffre mais écrit les produits côte à côte au lieu de les additionner selon leur valeur de position.",
"Products written side by side":"Produits écrits côte à côte",
