"Pip wrote the bottom digit when the top digit was zero.":"Pip a écrit le chiffre du bas quand celui du haut était zéro.",
"Pip wrote a two-digit sum in one place instead of making a ten.":"Pip a écrit une somme à deux chiffres dans une seule position au lieu de faire une dizaine.",
"Pip made a ten but forgot to add it to the tens.":"Pip a fait une dizaine mais a oublié de l'ajouter aux dizaines.",
