"With a parent's consent, the app keeps a child's nickname and birth year, and a record of their answers: which skill, whether it was right, which hints they used, which strategy they chose and how long they took, plus how close their number-line warm-up estimates were, the badges they earned and the look they chose for Pip.":"Avec le consentement d'un parent, l'application conserve le surnom et l'année de naissance de l'enfant, ainsi qu'un relevé de ses réponses : quelle compétence, si c'était juste, quels indices ont été utilisés, quelle stratégie a été choisie et le temps mis, plus la précision de ses estimations lors des échauffements sur la droite numérique, les badges gagnés et le look choisi pour Pip.",
