"Take away big groups first, then smaller ones.":"Enlève d'abord de grands groupes, puis de plus petits.",
"Take away big, easy groups first, like {N} or {N} groups.":"Enlève d'abord de grands groupes faciles, comme {N} ou {N} groupes.",
"Take away the hundreds.":"Soustrais les centaines.",
"Take away the top numbers.":"Soustrais les nombres du haut.",
"Take away what the groups use.":"Enlève ce que prennent les groupes.",
"Take away {N} of the pieces.":"Enlève {N} des parts.",
"Take that away.":"Enlève-le.",
"Tens times ones.":"Dizaines fois unités.",
"Tens times tens.":"Dizaines fois dizaines.",
"Tenths and hundredths are pieces of one whole.":"Les dixièmes et les centièmes sont des parts d'une unité.",
"That is all of it.":"C'est tout.",
"That is less than {N}, so round down.":"C'est moins de {N}, alors arrondis en dessous.",
"That is more than {N}, so it is too many.":"C'est plus que {N}, donc c'est trop.",
"That is what is left over.":"C'est ce qui reste.",
"That is {N} or more, so round up.":"C'est {N} ou plus, alors arrondis au-dessus.",
"That makes four parts.":"Ça fait quatre parties.",
"That makes it composite.":"Donc il est composé.",
"That makes it prime.":"Donc il est premier.",
"That part is the remainder, R.":"Cette partie, c'est le reste, R.",
"The bottom number is still {N}.":"Le nombre du bas reste {N}.",
"The bottom number stays the same.":"Le nombre du bas ne change pas.",
"The bottom number tells the size of the pieces.":"Le nombre du bas dit la taille des parts.",
"The digit just after the rounding place tells you.":"Le chiffre juste après le rang de l'arrondi te le dit.",
"The first digits that are different are in the hundred thousands place: {N} and {N}.":"Les premiers chiffres différents sont au rang des centaines de mille : {N} et {N}.",
"The first digits that are different are in the hundreds place: {N} and {N}.":"Les premiers chiffres différents sont au rang des centaines : {N} et {N}.",
"The first digits that are different are in the ones place: {N} and {N}.":"Les premiers chiffres différents sont au rang des unités : {N} et {N}.",
"The first digits that are different are in the ten thousands place: {N} and {N}.":"Les premiers chiffres différents sont au rang des dizaines de mille : {N} et {N}.",
"The first digits that are different are in the tens place: {N} and {N}.":"Les premiers chiffres différents sont au rang des dizaines : {N} et {N}.",
"The first digits that are different are in the thousands place: {N} and {N}.":"Les premiers chiffres différents sont au rang des milliers : {N} et {N}.",
"The first place after the point is tenths.":"Le premier rang après la virgule, ce sont les dixièmes.",
"The first place where the digits are different decides.":"C'est le premier rang où les chiffres sont différents qui décide.",
"The new thousand moves to the thousands.":"Le nouveau millier passe aux milliers.",
"The next is hundredths.":"Le suivant, ce sont les centièmes.",
"The number of groups is {N}.":"Le nombre de groupes est {N}.",
"The number {N} is neither.":"Le nombre {N} n'est ni l'un ni l'autre.",
"The pieces that are left make the fraction part.":"Les parts qui restent forment la partie fraction.",
"The rectangle has four parts.":"Le rectangle a quatre parties.",
"The remainder is always smaller than one group.":"Le reste est toujours plus petit qu'un groupe.",
"The remainder is {N}.":"Le reste est {N}.",
"The rule here is: add {N}.":"Ici, la règle est : ajouter {N}.",
"The rule here is: multiply by {N}.":"Ici, la règle est : multiplier par {N}.",
"The rule works.":"La règle marche.",
"The smaller bottom number means bigger pieces.":"Le nombre du bas le plus petit veut dire des parts plus grandes.",
"The tenths place gets a {N}.":"Au rang des dixièmes, on met un {N}.",
"The {N} in the hundreds place means {N}.":"Le {N} au rang des centaines veut dire {N}.",
"The {N} in the tens place means {N}.":"Le {N} au rang des dizaines veut dire {N}.",
"Their size does not change.":"Leur taille ne change pas.",
"Then break {N} hundred into {N} tens.":"Puis casse {N} centaine en {N} dizaines.",
"Then compare the top numbers.":"Puis compare les nombres du haut.",
"Then compare them like whole numbers: {N} > {N}.":"Puis compare-les comme des nombres entiers : {N} > {N}.",
"Then multiply the top and the bottom by that number.":"Puis multiplie le haut et le bas par ce nombre.",
"Then {N} of those hundreds went to the tens.":"Puis {N} de ces centaines est allée aux dizaines.",
"There are {N} hundreds too.":"Il y a aussi {N} centaines.",
"There are {N} tenths, and each is {N} hundredths.":"Il y a {N} dixièmes, et chacun fait {N} centièmes.",
"There is {N} tenth, and each is {N} hundredths.":"Il y a {N} dixième, et chacun fait {N} centièmes.",
"Times as many means equal groups.":"Fois plus, ça veut dire des groupes égaux.",
"To add, the pieces must be the same size.":"Pour additionner, les parts doivent avoir la même taille.",
"Try each choice.":"Essaie chaque choix.",
