"What {P} is working on, and why":"Ce sur quoi {P} travaille, et pourquoi",
"Builds on:":"S'appuie sur :",
"Opens next:":"Ouvre ensuite :",
"Place value is how our number system works.":"La valeur de position, c'est le fonctionnement de notre système de numération.",
"Written adding, subtracting and multiplying all lean on it.":"L'addition, la soustraction et la multiplication posées s'appuient toutes dessus.",
"Adding and subtracting come up in almost every later topic, from money to fractions.":"L'addition et la soustraction reviennent dans presque tous les sujets suivants, de l'argent aux fractions.",
"Multiplying and dividing are the base for fractions, area and most of Grades {N} and {N}.":"La multiplication et la division sont la base des fractions, de l'aire et de presque tout le niveau {N} et {N}.",
"Word problems connect the math to real situations: choosing what to do, not only how to do it.":"Les problèmes relient les maths à des situations réelles : choisir quoi faire, pas seulement comment le faire.",
"Patterns, expressions and mixed review keep skills connected and fresh.":"Les suites, les expressions et la révision mélangée gardent les compétences reliées et fraîches.",
"Fractions describe parts of a whole and lead to decimals and measurement.":"Les fractions décrivent des parties d'un tout et mènent aux décimaux et à la mesure.",
"Decimals extend place value past the ones place and are used for money and measuring.":"Les décimaux prolongent la valeur de position au-delà des unités et servent pour l'argent et la mesure.",
"Counting money uses place value and adding in a setting children meet every day.":"Compter de l'argent utilise la valeur de position et l'addition dans une situation que les enfants rencontrent chaque jour.",
"Reading clocks and finding time passed use counting by {N}s and the {N} minutes in an hour.":"Lire l'heure et trouver le temps écoulé utilisent le comptage de {N1} en {N1} et les {N2} minutes d'une heure.",
"Measuring connects numbers to real lengths, and area is a picture of multiplying.":"Mesurer relie les nombres à de vraies longueurs, et l'aire est une image de la multiplication.",
"Shapes, angles and grids are the start of geometry and of reading graphs and maps.":"Les formes, les angles et les quadrillages sont le début de la géométrie et de la lecture de graphiques et de cartes.",
"Every Grade {N} skill is lit, so Pip moves on.":"Toutes les compétences du niveau {N} sont allumées, alors Pip passe à la suite.",
