"Gives a price from the line when the question asks how much it changed.":"Donne un prix de la courbe quand la question demande de combien il a changé.",
"Gives the highest price when the question asks which week.":"Donne le prix le plus haut quand la question demande quelle semaine.",
"The question asks how much it changed.":"La question demande de combien il a changé.",
"Take one price from the other.":"Enlève un prix de l'autre.",
"The question asks which week.":"La question demande quelle semaine.",
"Look below the highest point.":"Regarde sous le point le plus haut.",
"Pip gave a price instead of how much it changed.":"Pip a donné un prix au lieu de la variation.",
"Pip gave the price instead of the week.":"Pip a donné le prix au lieu de la semaine.",
"Dollars and cents.":"Dollars et centimes.",
"A price like ${N} has dollars before the point and cents after it.":"Un prix comme {N} $ a les dollars avant la virgule et les centimes après.",
"Line up the decimal points to add or subtract.":"Aligne les virgules pour additionner ou soustraire.",
"Dollars go with dollars, cents go with cents.":"Les dollars avec les dollars, les centimes avec les centimes.",
