"Line up the decimal points: dollars with dollars, cents with cents.":"Aligne les virgules : les dollars avec les dollars, les centimes avec les centimes.",
"Read prices on a receipt together and say the dollars and the cents.":"Lisez ensemble les prix d'un ticket de caisse et dites les dollars et les centimes.",
"What does one cost?":"Combien coûte un seul ?",
"A pack price is for all the items in it.":"Le prix d'un paquet est pour tous les articles qu'il contient.",
"Divide the pack price by how many items.":"Divise le prix du paquet par le nombre d'articles.",
"That gives the price for one, called the unit price.":"Cela donne le prix d'un seul, appelé prix à l'unité.",
"Compare unit prices to find the better buy.":"Compare les prix à l'unité pour trouver le meilleur achat.",
"How many items are in the pack?":"Combien d'articles y a-t-il dans le paquet ?",
"The pack price divided by how many.":"Le prix du paquet divisé par le nombre.",
"At the store, find a pack and work out the price for one item together.":"Au magasin, trouvez un paquet et calculez ensemble le prix d'un article.",
"Prices go up and down.":"Les prix montent et descendent.",
"Each point shows the price in one week.":"Chaque point montre le prix d'une semaine.",
"Find the week along the bottom and the price up the side.":"Trouve la semaine en bas et le prix sur le côté.",
"Take one price from the other to find the change.":"Enlève un prix de l'autre pour trouver la variation.",
"Going up before does not mean it will go up again.":"Avoir monté avant ne veut pas dire que ça remontera.",
"Which two weeks does the question ask about?":"Sur quelles deux semaines porte la question ?",
"Find both prices, then take the smaller from the bigger.":"Trouve les deux prix, puis enlève le plus petit du plus grand.",
