"Shops try different prices: a higher price can mean fewer sales.":"Les magasins essaient différents prix : un prix plus élevé peut vouloir dire moins de ventes.",
"When costs are bigger than sales, a business has a loss that day.":"Quand les coûts sont plus grands que les ventes, une entreprise fait une perte ce jour-là.",
"Shoppers round prices to check quickly whether a list fits their money.":"Les clients arrondissent les prix pour vérifier vite si une liste tient dans leur budget.",
"Prices use a decimal point: dollars on the left, cents on the right.":"Les prix utilisent une virgule : les dollars à gauche, les centimes à droite.",
"Shelf labels often show the price for one, so shoppers can compare packs.":"Les étiquettes des rayons montrent souvent le prix à l'unité, pour comparer les paquets.",
"Friends who share a meal often divide the bill so each pays the same.":"Les amis qui partagent un repas divisent souvent l'addition pour que chacun paie pareil.",
"Some companies pay part of their profit to the people who own shares.":"Certaines entreprises versent une partie de leur bénéfice à ceux qui ont des actions.",
"Businesses compare the cost of one item in small and big packs.":"Les entreprises comparent le coût d'un article en petit et en grand paquet.",
"Money saved earlier has more years to grow.":"L'argent épargné plus tôt a plus d'années pour grandir.",
"The price of a share goes up and down; going up last week does not mean it will next week.":"Le prix d'une action monte et descend ; avoir monté la semaine dernière ne veut pas dire qu'il montera la suivante.",
"Ask: if a toy cost twice as much, would as many people buy it?":"Demandez : si un jouet coûtait deux fois plus cher, autant de gens l'achèteraient-ils ?",
"Talk about a time plans changed because of the weather, and what it cost.":"Parlez d'une fois où vos projets ont changé à cause du temps, et de ce que ça a coûté.",
"Before checkout, round each item on a short list and estimate the total together.":"Avant de payer, arrondissez chaque article d'une petite liste et estimez le total ensemble.",
"At the store, find two pack sizes of the same thing and work out the price for one.":"Au magasin, trouvez deux tailles de paquet de la même chose et calculez le prix d'un seul.",
"Share a pretend bill for a family meal and work out each person’s part.":"Partagez une addition pour de faux d'un repas de famille et calculez la part de chacun.",
"Ask: if a company makes more profit, what happens to each owner’s part?":"Demandez : si une entreprise fait plus de bénéfice, qu'arrive-t-il à la part de chaque propriétaire ?",
